import static org.junit.Assert.*;

/**
 * Unit tests for RealMatrixImpl#operate(double[] v).
 * Aiming for maximum branch and line coverage.
 */
public class RealMatrixImpl_operate_TriageGen2Test {

    private static final double DELTA = 1e-10;











    @Test
    public void testOperateWithNegativeValues() {
        double[][] data = {
            {-1.0, 2.0},
            {3.0, -4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        double[] v = {2.0, -1.0};
        // Row 0: (-1 * 2) + (2 * -1) = -2 - 2 = -4
        // Row 1: (3 * 2) + (-4 * -1) = 6 + 4 = 10
        double[] expected = {-4.0, 10.0};

        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, DELTA);
    }
}
